<script setup lang="ts">
import {computed,reactive,ref} from 'vue';import {useRoute} from 'vue-router';import {api} from '../lib/api';import {configured} from '../lib/firebase';import {privacyRequestSchema} from '../../shared/validation';
const route=useRoute();const title=computed(()=>({'/privacy':'הודעת פרטיות','/terms':'תנאי שימוש','/purpose':'מטרת הדיווח','/contact':'יצירת קשר','/accessibility':'נגישות','/privacy/contact':'פנייה בנושא פרטיות'}[route.path]||'העמוד לא נמצא'));
const form=reactive({fullName:'',email:'',type:'access',reference:'',message:'',consent:false,honeypot:''});const busy=ref(false);const error=ref('');const reference=ref('');
async function send(){error.value='';const parsed=privacyRequestSchema.safeParse(form);if(!parsed.success){error.value='יש למלא את הפרטים ולאשר את הסכמתכם לתיעוד הבקשה.';return;}busy.value=true;try{const result=await api<{reference:string}>('/api/privacy-requests',{method:'POST',body:JSON.stringify(parsed.data)});reference.value=result.reference;}catch(e){error.value=e instanceof Error?e.message:'השליחה נכשלה.';}finally{busy.value=false;}}
</script>
<template><main id="main-content" class="legal-main"><div class="container"><div class="breadcrumb"><RouterLink to="/">עמוד הבית</RouterLink> / {{title}}</div><div class="legal-heading"><h1>{{title}}</h1></div><div class="draft-notice">טיוטת תוכן למערכת בפיתוח. פרטי הגוף האחראי, מדיניות השמירה וערוצי הקשר מחייבים השלמה ואישור לפני השקה לציבור.</div><div class="legal-content">
<template v-if="route.path==='/privacy'"><h2>מי אחראי למידע?</h2><p>המערכת נבנית עבור מיזם ארגון צרכני התעופה בישראל. שם הגוף המשפטי, כתובתו ופרטי האחראי למידע יושלמו לפני השקה. אין בטיוטה קביעה בדבר רישום הארגון או מעמדו המשפטי.</p><h2>המידע הנאסף והמטרות</h2><p>המערכת אוספת פרטי קשר, תיאור אירוע, פרטי עסקה וטיסה, סכומים, מסמכים שנבחרו להעלאה והסכמות. אין בקשה למספר תעודת זהות. אין להעלות דרכון, פרטי אשראי מלאים או מידע עודף על צדדים שלישיים.</p><p>המידע מיועד לבחינת דיווחים וניתוח תופעות צרכניות. יצירת קשר בנוגע לבחינת הליך משפטי וקבלת עדכונים הן הסכמות נפרדות ואופציונליות, שאינן מסומנות מראש.</p><h2>גישה ואחסון</h2><p>דיווחים ומסמכים אינם מתפרסמים אוטומטית. הגישה באמצעות שרת מאובטח לצוות מורשה, בהתאם לתפקיד. ייצוא פרטים מזהים מוגבל למנהלים ונרשם ביומן. בענן נעשה שימוש ב־Firebase Authentication, Firestore ו־Cloud Storage. מיקום האחסון והסכמי העיבוד ייקבעו בעת הגדרת הפרויקט.</p><p>בסביבת הדגמה Firebase Emulator שומר נתונים מקומית בזיכרון תהליכי ההדגמה. יש להשתמש בה בנתונים פיקטיביים בלבד. אין לשמור נתוני אמת לפני אישור ההגדרות והמדיניות.</p><h2>שמירה בדפדפן</h2><p>טיוטת הדיווח ופרטי הכניסה לצוות נשמרים בזיכרון הדף. רענון או יציאה עשויים למחוק טיוטה ולדרוש כניסה מחדש. לא מופעל דיוור שיווקי או ניתוח ביקורים. App Check עשוי להפעיל reCAPTCHA Enterprise למניעת שימוש לרעה בסביבת הענן.</p><h2>שמירה, עיון, תיקון ומחיקה</h2><p>תקופות השמירה, טיפול בגיבויים ותהליך אימות זהות יוגדרו לפני השקה. <RouterLink to="/privacy/contact">אפשר להגיש פנייה בנושא פרטיות</RouterLink>. הבקשה מתועדת לצוות ואינה מפעילה מחיקה אוטומטית.</p></template>
<template v-else-if="route.path==='/terms'"><h2>שימוש במערכת</h2><p>יש למסור מידע נכון, בתום לב ולמיטב ידיעתכם, ולצרף רק מסמכים שאתם רשאים למסור. השימוש אינו כרוך בתשלום.</p><h2>בחינת הדיווח</h2><p>הגשת דיווח אינה מבטיחה מענה אישי, טיפול בתלונה, ייצוג משפטי, הגשת תביעה או פיצוי. המערכת אינה תחליף לייעוץ פרטני ואינה עוצרת מועדים. כל הליך נוסף דורש בחינה והסדרה נפרדת.</p><h2>מסמכים ותוכן</h2><p>אין להעלות תוכן בלתי חוקי או מידע שאינו נחוץ לבחינת האירוע. המערכת רשאית להגביל שימוש לרעה. מסירת המידע כפופה להודעת הפרטיות.</p></template>
<template v-else-if="route.path==='/purpose'"><h2>מחברים מקרים. מזהים דפוסים.</h2><p>הדיווח מאפשר לאסוף מידע מסודר על בעיות צרכניות בתחום התעופה והתיירות, לבחון מאפיינים משותפים ולהעריך צעדים אפשריים.</p><p>סימון דפוס במערכת הוא כלי עזר לבדיקה. הוא אינו קביעה משפטית, הוכחה להפרה או פרסום נגד חברה.</p><RouterLink to="/report" class="btn btn-primary">להגשת דיווח</RouterLink></template>
<template v-else-if="route.path==='/contact'"><h2>איך אפשר לפנות?</h2><p>לדיווח על אירוע צרכני השתמשו בטופס הדיווח. לעיון, תיקון או מחיקה של מידע השתמשו בטופס פנייה בנושא פרטיות.</p><p>כתובת דוא״ל ציבורית ופרטי הגוף האחראי טרם נקבעו ויושלמו לפני השקה.</p><RouterLink to="/report" class="btn btn-primary">דיווח על אירוע</RouterLink> <RouterLink to="/privacy/contact" class="btn btn-secondary">פנייה בנושא פרטיות</RouterLink></template>
<template v-else-if="route.path==='/accessibility'"><h2>שימוש נגיש</h2><p>המערכת כוללת תמיכה במקלדת, תוויות לשדות, מיקוד נראה, מבנה כותרות, קישור דילוג ותצוגה מותאמת למסכים קטנים. אפשר להגדיל טקסט בדפדפן.</p><p>טרם בוצעה בדיקת נגישות מקצועית מלאה ואין כאן הצהרה על עמידה בתקן. פרטי רכז נגישות ודרך לדיווח על תקלה יושלמו לפני השקה.</p></template>
<template v-else-if="route.path==='/privacy/contact'"><div v-if="reference" class="privacy-success"><h2>הפנייה התקבלה</h2><p>מספר פנייה: <strong dir="ltr">{{reference}}</strong></p><p>הפנייה תיבחן בידי צוות מורשה. קבלת הפנייה אינה מאשרת זהות ואינה מבצעת מחיקה.</p></div><form v-else @submit.prevent="send"><p>הפנייה תתועד לצורך בחינה. אין לצרף תעודה מזהה או מידע שאינו נחוץ.</p><div class="form-grid"><div class="field"><label for="pr-name">שם מלא</label><input id="pr-name" class="input" v-model="form.fullName" required maxlength="150"/></div><div class="field"><label for="pr-email">דוא״ל</label><input id="pr-email" class="input" v-model="form.email" type="email" dir="ltr" required/></div><div class="field"><label for="pr-type">סוג הבקשה</label><select id="pr-type" class="select" v-model="form.type"><option value="access">עיון במידע</option><option value="correction">תיקון מידע</option><option value="deletion">מחיקת מידע</option></select></div><div class="field"><label for="pr-reference">מספר דיווח, אם קיים</label><input id="pr-reference" class="input" v-model="form.reference" maxlength="100"/></div></div><div class="field"><label for="pr-message">תוכן הבקשה</label><textarea id="pr-message" class="textarea" v-model="form.message" required minlength="10" maxlength="4000"/></div><label class="consent-line"><input type="checkbox" v-model="form.consent" required/>אני מסכים/ה לתיעוד פרטי הבקשה לצורך בדיקה ומענה.</label><div style="display:none" aria-hidden="true"><input v-model="form.honeypot" tabindex="-1" autocomplete="off" aria-label="website"/></div><p v-if="error" class="alert alert-error" role="alert">{{error}}</p><button class="btn btn-primary" :disabled="busy||!configured">{{busy?'שולחים…':'שליחת בקשה'}}</button></form></template>
<template v-else><p>העמוד המבוקש לא נמצא.</p><RouterLink to="/">לעמוד הבית</RouterLink></template>
<p class="legal-version">גרסת טיוטה 2026-10 · יש לאשר תוכן ופרטי קשר לפני השקה</p></div></div></main></template>
